import{_ as o,o as c,c as t,a1 as s}from"./chunks/framework.BKrM4vFX.js";const _=JSON.parse('{"title":"mock-services 0.8.0 — 2026-10-16","description":"mock-services 0.8.0 — 2026-10-16. Первый релиз после большой предрелизной волны: десятый сервис (Такском), финальные волны безопасности, публичная документация на домене компании и чистовые лицензионные шапки. Такском — десятый мок-сервис (taxcom-mock, :","frontmatter":{"sourcePath":"docs/release-notes/v0.8.0.md"},"headers":[{"level":1,"title":"mock-services 0.8.0 — 2026-10-16","slug":"mock-services-080-2026-10-16","link":"#mock-services-080-2026-10-16","children":[{"level":2,"title":"Что нового","slug":"Что-нового","link":"#Что-нового","children":[]},{"level":2,"title":"Состав релиза","slug":"Состав-релиза","link":"#Состав-релиза","children":[]},{"level":2,"title":"Артефакты","slug":"Артефакты","link":"#Артефакты","children":[]}]}],"relativePath":"docs/release-notes/v0.8.0.md","filePath":"docs/release-notes/v0.8.0.md"}'),a={name:"docs/release-notes/v0.8.0.md"};function i(r,e,l,d,n,m){return c(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="mock-services-080-2026-10-16" tabindex="-1">mock-services 0.8.0 — 2026-10-16 <a class="header-anchor" href="#mock-services-080-2026-10-16" aria-label="Permalink to &quot;mock-services 0.8.0 — 2026-10-16&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#mock-services-080-2026-10-16">mock-services 0.8.0 — 2026-10-16</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Что-нового">Что нового</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Состав-релиза">Состав релиза</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Артефакты">Артефакты</a></li></ul></nav><p>Первый релиз после большой предрелизной волны: десятый сервис (Такском), финальные волны безопасности, публичная документация на домене компании и чистовые лицензионные шапки.</p><h2 id="Что-нового" tabindex="-1">Что нового <a class="header-anchor" href="#Что-нового" aria-label="Permalink to &quot;Что нового&quot;">​</a></h2><ul><li><strong>Такском — десятый мок-сервис</strong> (<code>taxcom-mock</code>, :3109): read-only кабинет/ОФД по API v2 — <code>Login</code> + <code>Integrator-ID</code> → <code>Session-Token</code>, договоры/личные кабинеты, документы за 10 суток с курсором; честные коды ошибок и DX-подсказки.</li><li><strong>Безопасность</strong>: управляющие токены вне URL (заголовки/cookie), hosted-режим fail-closed по умолчанию, graceful shutdown всех сервисов, контейнерный харденинг всех compose-контуров.</li><li><strong>Документация</strong>: публичный сайт — <a href="https://axiiom.ru/mock-services/" target="_blank" rel="noreferrer">https://axiiom.ru/mock-services/</a> (источник — этот репозиторий); гайды «интеграция за 10 минут» по всем 10 провайдерам, OpenAPI 3.1.</li><li><strong>Лицензия</strong>: шапки документов приведены к Apache-2.0, добавлен CI-страж; NOTICE и SPDX — без изменений.</li><li><strong>CI/релиз</strong>: полный гейт — для PR с кодом и тегов; релиз по тегу собирает образ (GHCR), архив-слепок и ноты.</li></ul><h2 id="Состав-релиза" tabindex="-1">Состав релиза <a class="header-anchor" href="#Состав-релиза" aria-label="Permalink to &quot;Состав релиза&quot;">​</a></h2><p>10 сервисов: <code>tbank-mock</code>, <code>kassa-mock</code> (Ferma), <code>yookassa-mock</code>, <code>atol-mock</code>, <code>alfa-mock</code>, <code>sber-mock</code>, <code>vtb-mock</code>, <code>first-ofd-mock</code>, <code>kontur-ofd-mock</code>, <code>taxcom-mock</code>; общее ядро, три compose-файла, Dockerfile, документация и OpenAPI.</p><h2 id="Артефакты" tabindex="-1">Артефакты <a class="header-anchor" href="#Артефакты" aria-label="Permalink to &quot;Артефакты&quot;">​</a></h2><ul><li><strong>Архив</strong>: <code>mock-services-0.8.0.zip</code> — слепок репозитория на теге (+ <code>.sha256</code>), вложения релиза.</li><li><strong>Образ</strong>: <code>ghcr.io/rucorp/mock-services:0.8.0</code> — диджест на странице GHCR.</li><li><strong>Документация</strong>: <a href="https://axiiom.ru/mock-services/" target="_blank" rel="noreferrer">https://axiiom.ru/mock-services/</a></li></ul><p>Полный список изменений — в <code>CHANGELOG.md</code>, раздел <code>[0.8.0]</code>.</p>',10)])])}const h=o(a,[["render",i]]);export{_ as __pageData,h as default};
